package vn.rtr.aeris.cockpit03;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import vn.rtr.aeris.beta01runtime.NativeSegments;
import vn.rtr.aeris.beta01runtime.Values;

/** Immutable content-addressed generations. Pending/conflict is visible, never repaired silently. */
public final class WorkspaceStore {
 public static final int MAX_BYTES=131072,MAX_FILES=256;public static final long QUOTA=16L*1024*1024;
 private final File root;private final NativeSegments.Sync sync;
 public WorkspaceStore(File root,NativeSegments.Sync sync)throws IOException{this.root=root;this.sync=sync;if(Files.isSymbolicLink(root.toPath()))throw new IOException("WORKSPACE_ROOT_SYMLINK");if(!root.exists()){if(!root.mkdir())throw new IOException("WORKSPACE_CREATE");sync.directory(root.getParentFile());}scan();}
 public synchronized List<File> scan()throws IOException{File[]all=root.listFiles();if(all==null||all.length>MAX_FILES)throw new IOException("WORKSPACE_COUNT");long total=0;ArrayList<File>out=new ArrayList<>();HashSet<Integer>drafts=new HashSet<>();HashSet<String>reviews=new HashSet<>();for(File f:all){String n=f.getName();if(Files.isSymbolicLink(f.toPath())||!f.isFile()||!n.matches("(draft-[0-9]{6}|review-[A-Za-z0-9_.:-]{1,128})-[a-f0-9]{64}\\.json"))throw new IOException("WORKSPACE_PENDING_OR_FOREIGN:"+n);byte[]b=read(f);if(!n.endsWith("-"+Values.hash(b)+".json"))throw new IOException("WORKSPACE_CONTENT_SHA");total+=b.length;if(n.startsWith("draft-")&&!drafts.add(Integer.parseInt(n.substring(6,12))))throw new IOException("WORKSPACE_REVISION_CONFLICT");if(n.startsWith("review-")&&!reviews.add(n.substring(0,n.length()-70)))throw new IOException("WORKSPACE_REVIEW_CONFLICT");out.add(f);}for(int i=1;i<=drafts.size();i++)if(!drafts.contains(i))throw new IOException("WORKSPACE_DRAFT_GENERATION_GAP");if(total>QUOTA)throw new IOException("WORKSPACE_QUOTA");out.sort(Comparator.comparing(File::getName));return out;}
 public synchronized int revision()throws IOException{int rev=0;for(File f:scan())if(f.getName().startsWith("draft-"))rev=Math.max(rev,Integer.parseInt(f.getName().substring(6,12)));return rev;}
 public synchronized File latestDraft()throws IOException{File latest=null;for(File f:scan())if(f.getName().startsWith("draft-"))latest=f;return latest;}
 public synchronized String saveDraft(int expectedRevision,byte[]canonical)throws IOException{if(expectedRevision!=revision()||expectedRevision>=999998)throw new IOException("WORKSPACE_REVISION_STALE");return commit(String.format(Locale.ROOT,"draft-%06d",expectedRevision+1),canonical);}
 public synchronized String saveReview(String run,byte[]canonical)throws IOException{if(run==null||!run.matches("[A-Za-z0-9_.:-]{1,128}"))throw new IOException("REVIEW_RUN");for(File f:scan())if(f.getName().substring(0,f.getName().length()-70).equals("review-"+run)){if(Arrays.equals(read(f),canonical))return Values.hash(canonical);throw new IOException("REVIEW_RUN_CONFLICT");}return commit("review-"+run,canonical);}
 private String commit(String stem,byte[]b)throws IOException{if(b==null||b.length==0||b.length>MAX_BYTES)throw new IOException("WORKSPACE_RECORD_BOUND");List<File>all=scan();long used=0;for(File f:all)used+=f.length();if(all.size()>=MAX_FILES||used+b.length>QUOTA||root.getUsableSpace()<NativeSegments.RESERVE+b.length)throw new IOException("WORKSPACE_QUOTA_OR_RESERVE");String hash=Values.hash(b);File dest=new File(root,stem+"-"+hash+".json"),pending=new File(root,stem+".pending"),intent=new File(root,stem+".commit.pending");if(!intent.createNewFile())throw new IOException("WORKSPACE_INTENT_EXISTS");try(FileOutputStream out=new FileOutputStream(intent)){out.write(hash.getBytes(java.nio.charset.StandardCharsets.US_ASCII));sync.file(out.getFD());}sync.directory(root);if(!pending.createNewFile())throw new IOException("WORKSPACE_PENDING_EXISTS");try(FileOutputStream out=new FileOutputStream(pending)){out.write(b);sync.file(out.getFD());}if(dest.exists()||!pending.renameTo(dest))throw new IOException("WORKSPACE_RENAME");sync.directory(root);if(!intent.delete())throw new IOException("WORKSPACE_INTENT_REMAINS");return hash;}
 public static byte[]read(File f)throws IOException{if(f.length()>MAX_BYTES)throw new IOException("WORKSPACE_READ_BOUND");return Files.readAllBytes(f.toPath());}
}
